begin;
create table clinic_finance.legacy_assets(id uuid primary key default gen_random_uuid(),subject text not null,reference text not null unique,payload jsonb not null,created_by uuid not null references public.admins(id),token uuid not null,created_at timestamptz not null default now(),status text not null default 'pending' check(status in ('pending','approved','rejected')),asset_id uuid references clinic_finance.business_requests(id),reviewed_by uuid references public.admins(id),review_note text,unique(created_by,token));
create function public.clinic_finance_legacy_asset(p_action text,p_payload jsonb,p_token uuid) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$
declare me uuid:=clinic_finance.require_access('create');r clinic_finance.legacy_assets%rowtype;v uuid;asset uuid;cost numeric;accum numeric;residual numeric;n integer;elapsed integer;j text;begin perform clinic_finance.lock_day();
if exists(select 1 from clinic_finance.manual_batches where kind='opening' and status='approved') then raise exception 'استيراد الأصول القديمة يجب أن يسبق اعتماد الافتتاح العام';end if;
if p_action='request' then
 select * into r from clinic_finance.legacy_assets where created_by=me and token=p_token;if found then if r.payload<>p_payload then raise exception 'مفتاح مستخدم لبيانات أخرى';end if;return r.id;end if;
 if coalesce(length(trim(p_payload->>'subject')),0)<2 or coalesce(length(trim(p_payload->>'reference')),0)<2 or coalesce(length(trim(p_payload->>'note')),0)<3 then raise exception 'بيانات الأصل والمستند مطلوبة';end if;
 foreach j in array array['amount','accumulated','residual'] loop if p_payload->>j is null or p_payload->>j in ('NaN','Infinity','-Infinity') or (p_payload->>j)::numeric<0 or (p_payload->>j)::numeric<>round((p_payload->>j)::numeric,2) then raise exception 'مبالغ الأصل غير صالحة';end if;end loop;
 cost:=(p_payload->>'amount')::numeric;accum:=(p_payload->>'accumulated')::numeric;residual:=(p_payload->>'residual')::numeric;n:=(p_payload->>'months')::integer;elapsed:=(p_payload->>'elapsed')::integer;
 if cost<=0 or residual>=cost or accum>cost-residual or n is null or n not between 1 and 1200 or elapsed is null or elapsed not between 0 and n or nullif(p_payload->>'start','') is null or (date_trunc('month',(p_payload->>'start')::date)+make_interval(months=>elapsed))::date>date_trunc('month',now())::date then raise exception 'العمر أو الأشهر السابقة أو تاريخ التشغيل أو مجمع الإهلاك غير صالح';end if;
 if elapsed=n and accum<>cost-residual then raise exception 'الأصل المنتهي عمره يجب أن يطابق القيمة المتبقية';end if;
 insert into clinic_finance.legacy_assets(subject,reference,payload,created_by,token) values(trim(p_payload->>'subject'),trim(p_payload->>'reference'),p_payload,me,p_token) returning id into v;
elsif p_action='review' then
 perform clinic_finance.require_access('review');select * into r from clinic_finance.legacy_assets where id=(p_payload->>'id')::uuid for update;if not found or r.status<>'pending' or r.created_by=me or coalesce(length(trim(p_payload->>'note')),0)<3 then raise exception 'يلزم أصل معلق ومراجع آخر وسبب القرار';end if;v:=r.id;
 if (p_payload->>'approve')::boolean then
 if exists(select 1 from clinic_finance.business_requests where kind='asset' and status='approved' and subject=r.subject) then raise exception 'معرف الأصل مسجل بالفعل';end if;
 cost:=(r.payload->>'amount')::numeric;accum:=(r.payload->>'accumulated')::numeric;
 insert into clinic_finance.business_requests(kind,subject,reference,amount,payload,created_by,token,status,reviewed_by,review_note) values('asset',r.subject,'LEGACY-'||r.reference,cost,r.payload||jsonb_build_object('opening_accumulated',accum,'opening_elapsed',(r.payload->>'elapsed')::integer,'method','opening'),r.created_by,gen_random_uuid(),'approved',me,p_payload->>'note') returning id into asset;
 perform clinic_finance.post('legacy_asset_cost',v,'تكلفة أصل افتتاحية '||r.reference,null,'1211','3199',cost);if accum>0 then perform clinic_finance.post('legacy_asset_accumulated',v,'مجمع إهلاك افتتاحي '||r.reference,null,'3199','1291',accum);end if;
 update clinic_finance.legacy_assets set asset_id=asset where id=v;
 end if;
 update clinic_finance.legacy_assets set status=case when (p_payload->>'approve')::boolean then 'approved' else 'rejected' end,reviewed_by=me,review_note=p_payload->>'note' where id=v;
else raise exception 'إجراء غير معروف';end if;insert into clinic_finance.audit(actor,action,entity_id) values(me,'legacy_asset_'||p_action,v);return v;end $$;
do $$declare def text;patched text;begin def:=pg_get_functiondef('public.clinic_finance_business_command(text,jsonb,uuid)'::regprocedure);patched:=replace(def,$s$payload->>'asset_id'=c.id::text;$s$,$s$payload->>'asset_id'=c.id::text;months:=months+coalesce((c.payload->>'opening_elapsed')::integer,0);used:=used+coalesce((c.payload->>'opening_accumulated')::numeric,0);$s$);if patched=def then raise exception 'Missing depreciation patch target';end if;execute patched;end $$;
alter function public.clinic_finance_snapshot(date,date,integer) set schema clinic_finance;
alter function clinic_finance.clinic_finance_snapshot(date,date,integer) rename to legacy_asset_snapshot_base;
create function public.clinic_finance_snapshot(p_from date,p_to date,p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare v jsonb:=clinic_finance.legacy_asset_snapshot_base(p_from,p_to,p_offset);me uuid:=clinic_finance.require_access('view');begin if clinic_finance.allowed('create') or clinic_finance.allowed('review') then v:=v||jsonb_build_object('fixed_assets',(select coalesce(jsonb_agg(x),'[]') from(select c.id,c.subject,c.amount,c.payload,c.amount-coalesce((c.payload->>'opening_accumulated')::numeric,0)-coalesce((select sum(amount) from clinic_finance.business_requests where kind='depreciation' and status='approved' and payload->>'asset_id'=c.id::text),0) book_value from clinic_finance.business_requests c where c.kind='asset' and c.status='approved' and (clinic_finance.allowed('review') or c.created_by=me))x),'legacy_assets',(select coalesce(jsonb_agg(x),'[]') from(select * from clinic_finance.legacy_assets where clinic_finance.allowed('review') or created_by=me order by created_at desc limit 200 offset p_offset)x));end if;return v;end $$;
-- Close must also wait for historical asset import reviews.
alter function public.clinic_finance_close_period(date) set schema clinic_finance;
alter function clinic_finance.clinic_finance_close_period(date) rename to legacy_close_period_base;
create function public.clinic_finance_close_period(p_through date) returns date language plpgsql security definer set search_path=pg_catalog,public as $$begin perform clinic_finance.require_access('review');perform clinic_finance.lock_day();if exists(select 1 from clinic_finance.legacy_assets where status='pending' and (created_at at time zone 'Africa/Cairo')::date<=p_through) then raise exception 'توجد أصول افتتاحية معلقة';end if;return clinic_finance.legacy_close_period_base(p_through);end $$;
alter function public.clinic_finance_manual_command(text,jsonb,uuid) set schema clinic_finance;
alter function clinic_finance.clinic_finance_manual_command(text,jsonb,uuid) rename to legacy_manual_base;
create function public.clinic_finance_manual_command(p_action text,p_payload jsonb,p_token uuid) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$begin perform clinic_finance.require_access('review');perform clinic_finance.lock_day();if p_action='review' and (p_payload->>'approve')::boolean and exists(select 1 from clinic_finance.manual_batches where id=(p_payload->>'id')::uuid and kind='opening') and (exists(select 1 from clinic_finance.legacy_assets where status='pending') or exists(select 1 from clinic_finance.advances where status='pending' and coalesce((payload->>'legacy')::boolean,false))) then raise exception 'راجع استيراد الأصول والمقدمات القديمة قبل اعتماد الافتتاح العام';end if;return clinic_finance.legacy_manual_base(p_action,p_payload,p_token);end $$;
revoke all on function public.clinic_finance_manual_command(text,jsonb,uuid) from public,anon;
grant execute on function public.clinic_finance_manual_command(text,jsonb,uuid) to authenticated;
alter table clinic_finance.legacy_assets enable row level security;
revoke all on all tables in schema clinic_finance from public,anon,authenticated;
revoke all on all functions in schema clinic_finance from public,anon,authenticated;
revoke all on function public.clinic_finance_legacy_asset(text,jsonb,uuid),public.clinic_finance_snapshot(date,date,integer),public.clinic_finance_close_period(date) from public,anon;
grant execute on function public.clinic_finance_legacy_asset(text,jsonb,uuid),public.clinic_finance_snapshot(date,date,integer),public.clinic_finance_close_period(date) to authenticated;
commit;
